update public.campaign_content_entries set payload=jsonb_set(payload,ARRAY['traits']::text[],'[{"name":"Regeneración","usage":"","content":"Recupera 10 PG al inicio de su turno.\n\nLa regeneración deja de funcionar hasta el inicio de su siguiente turno si recibe:\n\nDaño de fuego; daño ácido.\n\nSi comienza su turno con 0 PG y sin haber recibido fuego o ácido desde su último turno, recupera 10 PG."},{"name":"Sangre Congelante","usage":"","content":"Cuando una criatura golpea al troll con un ataque cuerpo a cuerpo desde 5 ft. o menos, recibe:\n\n5 (1d10) de daño por frío."},{"name":"Variante Luciente (opcional)","usage":"","content":"Como estos trolls viven junto a la gran grieta de cristales lucientes, puedes añadir el siguiente rasgo a algunos individuos sin alterar demasiado la dificultad.\n\nMutación Cristalina.\n\nCuando el troll cae por debajo de la mitad de sus puntos de golpe, fragmentos cristalinos emergen de su piel.\n\nDurante el resto del combate:\n\nobtiene ventaja en salvaciones contra magia. Inflige 1d6 daño radiante con todos sus ataques.\n\nVisualmente, esta transformación debería resultar inquietante para los jugadores, pues constituye una de las primeras evidencias de que los cristales lucientes alteran profundamente a los seres vivos."}]'::jsonb,false),revision=revision+1,updated_at=clock_timestamp() where kind='monster' and content_key='imported:monster:legacy:be0e81d85f7ca25d150d36c4' and campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and revision=2 and (payload #> ARRAY['traits']::text[]) = '[{"name":"Regeneración","usage":"","content":"Recupera 10 PG al inicio de su turno."},{"name":"La regeneración deja de funcionar hasta el inicio de su siguiente turno si recibe:","usage":"","content":""},{"name":"Daño de fuego; daño ácido.","usage":"","content":""},{"name":"Si comienza su turno con 0 PG y sin haber recibido fuego o ácido desde su último turno, recupera 10 PG.","usage":"","content":""},{"name":"Sangre Congelante","usage":"","content":"Cuando una criatura golpea al troll con un ataque cuerpo a cuerpo desde 5 ft. o menos, recibe:"},{"name":"5 (1d10) de daño por frío.","usage":"","content":""},{"name":"Variante Luciente (opcional)","usage":"","content":"Como estos trolls viven junto a la gran grieta de cristales lucientes, puedes añadir el siguiente rasgo a algunos individuos sin alterar demasiado la dificultad."},{"name":"Mutación Cristalina.","usage":"","content":""},{"name":"Cuando el troll cae por debajo de la mitad de sus puntos de golpe, fragmentos cristalinos emergen de su piel.","usage":"","content":""},{"name":"Durante el resto del combate:","usage":"","content":""},{"name":"obtiene ventaja en salvaciones contra magia. Inflige 1d6 daño radiante con todos sus ataques.","usage":"","content":""},{"name":"Visualmente, esta transformación debería resultar inquietante para los jugadores, pues constituye una de las primeras evidencias de que los cristales lucientes alteran profundamente a los seres vivos.","usage":"","content":""}]'::jsonb;
